    51	  // unbinding it. No macOS binding at all is different -- unbound there, so
    52	  // unbound here ([]). Same as the Linux default: nothing to say.
    53	  if (mac.length > 0 && free.length === 0) continue;
    54	  if (JSON.stringify(free) === JSON.stringify(kb.getDefaultBindings(def, 'linux'))) continue;
